import re


_DIGIT_READING = {1: '일', 2: '이', 3: '삼', 4: '사', 5: '오',
                  6: '육', 7: '칠', 8: '팔', 9: '구'}
_SMALL_UNIT = {1: '십', 2: '백', 3: '천'}
_BIG_UNIT = {1: '만', 2: '억', 3: '조'}


def _last_syllable_of_number(digits: str) -> str:
    value = int(digits)
    if value == 0:
        return '영'
    s = str(value)
    # position of lowest nonzero digit (0 = ones place)
    p = 0
    while s[-1 - p] == '0':
        p += 1
    d = int(s[-1 - p])
    if p == 0:
        return _DIGIT_READING[d]
    if p % 4 == 0:
        return _BIG_UNIT.get(p // 4, '조')
    return _SMALL_UNIT[p % 4]


def _has_batchim(syllable: str) -> bool:
    return (ord(syllable) - 0xAC00) % 28 != 0


def _has_rieul(syllable: str) -> bool:
    return (ord(syllable) - 0xAC00) % 28 == 8


def attach_particle(word: str, particle: str) -> str:
    m = re.search(r'\d+$', word)
    if m:
        last = _last_syllable_of_number(m.group())
    else:
        last = word[-1]

    before, after = particle.split('/')

    if particle == '으로/로':
        use_before = _has_batchim(last) and not _has_rieul(last)
    else:
        use_before = _has_batchim(last)

    return word + (before if use_before else after)
